/**
 * @file macho.c
 * @brief 32-bit Mach-O loader (MH_EXECUTE, ARMv6 / ARMv7) for PlayStation Vita.
 * @details
 * 1. __TEXT is assembled in temporary memory and copied to an RX block via kubridge;
 *    __DATA is mapped to a contiguous RW block preserving inter-segment distance (PIC).
 * 2. rebase.bin (generated by tools/macho_prep.py) lists absolute __DATA pointers to relocate with MACHO_SLIDE.
 * 3. Imports: resolves dynamic imports intercepting calls to iOS / Darwin / UIKit libraries.
 *    Any unresolved symbol routes to an automatic logging thunk that returns 0.
 */
#include <kubridge.h>
#include <psp2/kernel/sysmem.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "imports.h"
#include "log.h"
#include "macho.h"

#define LC_SEGMENT 0x1
#define LC_SYMTAB 0x2
#define LC_DYSYMTAB 0xB
#define LC_ENCRYPTION_INFO 0x21

#define S_ZEROFILL 0x1
#define S_NON_LAZY_SYMBOL_POINTERS 0x6
#define S_LAZY_SYMBOL_POINTERS 0x7

#define INDIRECT_SYMBOL_LOCAL 0x80000000u
#define INDIRECT_SYMBOL_ABS 0x40000000u

#define N_STAB 0xE0
#define N_TYPE 0x0E
#define N_SECT 0x0E
#define N_ARM_THUMB_DEF 0x0008

#ifndef SCE_KERNEL_MEMBLOCK_TYPE_USER_RX
#define SCE_KERNEL_MEMBLOCK_TYPE_USER_RX 0x0C20D050
#endif

#define ALIGN(x, a) (((x) + (a)-1) & ~((a)-1))
#define THUNK_ARENA_SIZE 0x20000

typedef struct {
    uint32_t cmd, cmdsize;
    char segname[16];
    uint32_t vmaddr, vmsize, fileoff, filesize, maxprot, initprot, nsects, flags;
} segment_command;

typedef struct {
    char sectname[16], segname[16];
    uint32_t addr, size, offset, align, reloff, nreloc, flags, reserved1, reserved2;
} section;

typedef struct {
    uint32_t n_strx;
    uint8_t n_type, n_sect;
    uint16_t n_desc;
    uint32_t n_value;
} nlist;

typedef struct {
    uint32_t ilocalsym, nlocalsym, iextdefsym, nextdefsym, iundefsym, nundefsym, tocoff, ntoc,
        modtaboff, nmodtab, extrefsymoff, nextrefsyms, indirectsymoff, nindirectsyms, extreloff,
        nextrel, locreloff, nlocrel;
} dysymtab_command;

static uint8_t *file_data;
static uint32_t file_slice_offset = 0;
static nlist *symtab;
static uint32_t nsyms;
static const char *strtab;
static uint32_t text_vm, text_size, data_vm, data_size;
static uint8_t *text_buf;
static uintptr_t text_real;
static uint32_t mod_init_addr, mod_init_count;

static uint32_t *thunk_head, *thunk_end;
static const char **unimpl_names;
static int unimpl_count;

extern void ml_unimpl_entry(void);
extern void ml_align_call(void);

void ml_unimpl_log(int idx) {
    static uint8_t seen[4096];
    if (idx < (int)sizeof(seen) && seen[idx] < 3) {
        seen[idx]++;
        l_warn("unimpl import: %s%s", unimpl_names[idx], seen[idx] == 3 ? " (silenced)" : "");
    }
}

static uintptr_t make_thunk(uint32_t ip_value, void *jump) {
    if (thunk_head + 4 > thunk_end)
        fatal_error("Thunk arena exhausted");
    uint32_t code[4] = {
        0xE59FC000, // ldr ip, [pc, #0]
        0xE59FF000, // ldr pc, [pc, #0]
        ip_value,
        (uint32_t)jump,
    };
    uintptr_t addr = (uintptr_t)thunk_head;
    kuKernelCpuUnrestrictedMemcpy(thunk_head, code, sizeof(code));
    kuKernelFlushCaches(thunk_head, sizeof(code));
    thunk_head += 4;
    return addr;
}

static uintptr_t make_unimpl_thunk(const char *name) {
    unimpl_names = realloc(unimpl_names, (unimpl_count + 1) * sizeof(char *));
    unimpl_names[unimpl_count] = name;
    return make_thunk(unimpl_count++, ml_unimpl_entry);
}

static uintptr_t make_unimpl_data(const char *name) {
    static struct {
        const char *name;
        uintptr_t addr;
    } blocks[512];
    static int nblocks;
    for (int i = 0; i < nblocks; i++)
        if (!strcmp(blocks[i].name, name))
            return blocks[i].addr;
    void *b = calloc(1, 256);
    if (nblocks < 512)
        blocks[nblocks++] = (typeof(blocks[0])){name, (uintptr_t)b};
    return (uintptr_t)b;
}

static uintptr_t *sym_cache;

// ObjC class/metaclass, CF constant and empty-cache imports are data, not code
static int is_data_import(const char *n) {
    return !strncmp(n, "_OBJC_", 6) || !strncmp(n, "__objc_", 7) || !strncmp(n, "___CF", 5) ||
           (n[0] == '_' && n[1] == 'k' && n[2] >= 'A' && n[2] <= 'Z');
}

static uintptr_t resolve_sym(uint32_t idx) {
    if (idx >= nsyms)
        fatal_error("Symbol index %u out of range (%u)", (unsigned)idx, (unsigned)nsyms);
    if (sym_cache[idx])
        return sym_cache[idx];
    nlist *s = &symtab[idx];
    const char *name = strtab + s->n_strx;
    const import_entry *imp;
    uintptr_t a;
    if (!(s->n_type & N_STAB) && (s->n_type & N_TYPE) == N_SECT) {
        a = MACHO_SLIDE + s->n_value;
        if (s->n_desc & N_ARM_THUMB_DEF)
            a |= 1;
    } else if ((imp = imports_lookup(name))) {
        a = imp->data ? imp->addr : make_thunk(imp->addr, ml_align_call);
    } else {
        a = is_data_import(name) ? make_unimpl_data(name) : make_unimpl_thunk(name);
    }
    return sym_cache[idx] = a;
}

// Pointer to a guest word: __TEXT words live in text_buf until the final copy
static uint32_t *guest_word(uint32_t va) {
    if (va >= text_vm && va < text_vm + text_size)
        return (uint32_t *)(text_buf + (va - text_vm));
    if (va >= data_vm && va < data_vm + data_size)
        return (uint32_t *)(MACHO_SLIDE + va);
    fatal_error("Relocation outside image: 0x%08X", (unsigned)va);
    return NULL;
}

// Sorted (name, runtime_addr) view of defined symbols: macho_sym is O(log n) (objc_get_class and
// imports resolve thousands of names).
typedef struct {
    const char *name;
    uintptr_t addr;
} sym_ent;
static sym_ent *sym_sorted;
static uint32_t sym_sorted_count;

static int sym_cmp(const void *a, const void *b) {
    return strcmp(((const sym_ent *)a)->name, ((const sym_ent *)b)->name);
}

static void build_sym_sorted(void) {
    if (sym_sorted || !symtab || !strtab)
        return;
    sym_sorted = calloc(nsyms ? nsyms : 1, sizeof(*sym_sorted));
    if (!sym_sorted)
        return;
    for (uint32_t i = 0; i < nsyms; i++) {
        nlist *s = &symtab[i];
        if (s->n_type & N_STAB || (s->n_type & N_TYPE) != N_SECT)
            continue;
        uintptr_t a = MACHO_SLIDE + s->n_value;
        if (s->n_desc & N_ARM_THUMB_DEF)
            a |= 1;
        sym_sorted[sym_sorted_count++] = (sym_ent){strtab + s->n_strx, a};
    }
    qsort(sym_sorted, sym_sorted_count, sizeof(*sym_sorted), sym_cmp);
}

uintptr_t macho_sym(const char *name) {
    build_sym_sorted();
    uint32_t lo = 0, hi = sym_sorted_count;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        int c = strcmp(sym_sorted[mid].name, name);
        if (c == 0)
            return sym_sorted[mid].addr;
        if (c < 0)
            lo = mid + 1;
        else
            hi = mid;
    }
    return 0;
}

// Loader import table first, then symbols defined inside the guest (alcGetProcAddress & co).
uintptr_t macho_resolve(const char *name) {
    const import_entry *imp = imports_lookup(name);
    if (imp)
        return imp->data ? imp->addr : make_thunk(imp->addr, ml_align_call);
    return macho_sym(name);
}

void macho_hook(const char *name, void *dst) {
    uintptr_t a = macho_sym(name);
    if (!a) {
        l_warn("macho_hook: symbol '%s' not found", name);
        return;
    }
    uint32_t code[4] = {
        0xE59FC000, // ldr ip, [pc, #0]
        0xE59FF000, // ldr pc, [pc, #0]
        (uint32_t)dst,
        (uint32_t)dst,
    };
    kuKernelCpuUnrestrictedMemcpy((void *)(a & ~1), code, sizeof(code));
    kuKernelFlushCaches((void *)(a & ~1), sizeof(code));
}

static void apply_rebase(const char *rebase_path) {
    FILE *f = fopen(rebase_path, "rb");
    if (!f) {
        fatal_error("Missing %s (run tools/stage_data.sh)", rebase_path);
    }
    uint32_t magic = 0, count = 0;
    // Without the rebase every slid pointer is wrong and the first constructor jumps to 0x000xxxxx
    if (fread(&magic, 4, 1, f) != 1 || magic != 0x31534252 /* RBS1 */ || fread(&count, 4, 1, f) != 1)
        fatal_error("Corrupt %s (bad RBS1 header; truncated upload? redeploy data)", rebase_path);

    uint32_t *entries = malloc(count * sizeof(uint32_t));
    if (!entries)
        fatal_error("Insufficient memory for %u rebase words", (unsigned)count);
    if (fread(entries, sizeof(uint32_t), count, f) != count)
        fatal_error("Truncated %s (expected %u words)", rebase_path, (unsigned)count);
    fclose(f);

    l_info("Applying %u rebase words from %s...", (unsigned)count, rebase_path);
    int applied = 0;
    for (uint32_t i = 0; i < count; i++) {
        uint32_t va = entries[i];
        if (va >= data_vm && va < data_vm + data_size) {
            uint32_t *ptr = (uint32_t *)(MACHO_SLIDE + va);
            *ptr += MACHO_SLIDE;
            applied++;
        } else if (va >= text_vm && va < text_vm + text_size) {
            // Rebase on text section stubs
            uint32_t *ptr = (uint32_t *)(text_buf + (va - text_vm));
            *ptr += MACHO_SLIDE;
            applied++;
        }
    }
    free(entries);
    l_info("Rebase complete: %d words relocated.", applied);
}

int macho_load(const char *bin_path, const char *rebase_path) {
    l_info("Loading Mach-O executable: %s", bin_path);
    FILE *f = fopen(bin_path, "rb");
    if (!f)
        fatal_error("Failed to open %s", bin_path);
    fseek(f, 0, SEEK_END);
    size_t file_len = ftell(f);
    fseek(f, 0, SEEK_SET);

    uint8_t *raw = malloc(file_len);
    if (!raw)
        fatal_error("Insufficient memory to load %s", bin_path);
    fread(raw, 1, file_len, f);
    fclose(f);

    uint8_t *d = raw;
    file_slice_offset = 0;

    // Detect FAT universal Mach-O (big-endian 0xCAFEBABE)
    if (file_len >= 8 && (memcmp(raw, "\xca\xfe\xba\xbe", 4) == 0 || memcmp(raw, "\xbe\xba\xfe\xca", 4) == 0)) {
        uint32_t nfat = (raw[4] << 24) | (raw[5] << 16) | (raw[6] << 8) | raw[7];
        uint32_t chosen_offset = 0, chosen_size = 0;
        const char *arch_name = "arm";
        for (uint32_t i = 0; i < nfat; i++) {
            const uint8_t *arch_ptr = raw + 8 + i * 20;
            uint32_t cputype = (arch_ptr[0] << 24) | (arch_ptr[1] << 16) | (arch_ptr[2] << 8) | arch_ptr[3];
            uint32_t cpusub = (arch_ptr[4] << 24) | (arch_ptr[5] << 16) | (arch_ptr[6] << 8) | arch_ptr[7];
            uint32_t off = (arch_ptr[8] << 24) | (arch_ptr[9] << 16) | (arch_ptr[10] << 8) | arch_ptr[11];
            uint32_t sz = (arch_ptr[12] << 24) | (arch_ptr[13] << 16) | (arch_ptr[14] << 8) | arch_ptr[15];
            if (cputype == 12 /* CPU_TYPE_ARM */) {
                if (cpusub == 9 /* v7 */ || cpusub == 11 /* v7s */) {
                    chosen_offset = off;
                    chosen_size = sz;
                    arch_name = "armv7";
                    break;
                } else if (cpusub == 6 /* v6 */ && !chosen_offset) {
                    chosen_offset = off;
                    chosen_size = sz;
                    arch_name = "armv6";
                }
            }
        }
        if (chosen_offset && chosen_offset + chosen_size <= file_len) {
            l_info("FAT binary detected: selected slice %s (offset 0x%X, size %u KB)",
                   arch_name, (unsigned)chosen_offset, (unsigned)(chosen_size / 1024));
            d = raw + chosen_offset;
            file_slice_offset = chosen_offset;
        }
    }

    file_data = d;
    uint32_t magic = *(uint32_t *)d;
    if (magic != 0xFEEDFACE)
        fatal_error("Invalid Mach-O magic header (0x%08X != 0xFEEDFACE)", (unsigned)magic);

    uint32_t ncmds = *(uint32_t *)(d + 16);
    uint32_t off = 28;

    dysymtab_command *dysym = NULL;
    segment_command *seg_text = NULL, *seg_data = NULL;
    section *sects[64];
    int nsects_total = 0;

    for (uint32_t c = 0; c < ncmds; c++) {
        uint32_t cmd = *(uint32_t *)(d + off);
        uint32_t size = *(uint32_t *)(d + off + 4);
        if (cmd == LC_SEGMENT) {
            segment_command *s = (segment_command *)(d + off);
            if (!strcmp(s->segname, "__TEXT"))
                seg_text = s;
            else if (!strcmp(s->segname, "__DATA"))
                seg_data = s;
            section *sec = (section *)(d + off + 56);
            for (uint32_t i = 0; i < s->nsects && nsects_total < 64; i++)
                sects[nsects_total++] = &sec[i];
        } else if (cmd == LC_SYMTAB) {
            uint32_t *p = (uint32_t *)(d + off + 8);
            symtab = (nlist *)(d + p[0]);
            nsyms = p[1];
            strtab = (const char *)(d + p[2]);
        } else if (cmd == LC_DYSYMTAB) {
            dysym = (dysymtab_command *)(d + off + 8);
        } else if (cmd == LC_ENCRYPTION_INFO) {
            uint32_t cryptid = *(uint32_t *)(d + off + 16);
            if (cryptid != 0) {
                l_error("================================================================");
                l_error("CRITICAL ALERT: Binary contains FairPlay DRM encryption (cryptid %u)!", (unsigned)cryptid);
                l_error("Cannot execute encrypted binary on PS Vita. Must be decrypted first.");
                l_error("================================================================");
            }
        }
        off += size;
    }

    if (!seg_text || !seg_data)
        fatal_error("Mach-O does not contain __TEXT or __DATA segments");

    text_vm = seg_text->vmaddr;
    text_size = ALIGN(seg_text->vmsize, 0x1000);
    data_vm = seg_data->vmaddr;
    data_size = ALIGN(seg_data->vmsize, 0x1000);

    l_info("__TEXT vm: 0x%08X (size 0x%08X) -> real 0x%08X",
           (unsigned)text_vm, (unsigned)text_size, (unsigned)(MACHO_SLIDE + text_vm));
    l_info("__DATA vm: 0x%08X (size 0x%08X) -> real 0x%08X",
           (unsigned)data_vm, (unsigned)data_size, (unsigned)(MACHO_SLIDE + data_vm));

    // Memory block allocations
    // Segments must live at MACHO_SLIDE + vmaddr: fixed-vbase blocks via kubridge (as so_util does)
    SceKernelAllocMemBlockKernelOpt opt = {0};
    opt.size = sizeof(opt);
    opt.attr = 0x1; // HAS_VBASE
    opt.field_C = MACHO_SLIDE + text_vm;
    SceUID text_blk = kuKernelAllocMemBlock("macho_text", SCE_KERNEL_MEMBLOCK_TYPE_USER_RX, text_size, &opt);
    if (text_blk < 0)
        fatal_error("kuKernelAllocMemBlock(text @0x%08X) = 0x%08X", (unsigned)opt.field_C, (unsigned)text_blk);
    void *text_ptr = NULL;
    sceKernelGetMemBlockBase(text_blk, &text_ptr);
    text_real = (uintptr_t)text_ptr;

    opt.field_C = MACHO_SLIDE + data_vm;
    SceUID data_blk = kuKernelAllocMemBlock("macho_data", SCE_KERNEL_MEMBLOCK_TYPE_USER_RW, data_size, &opt);
    if (data_blk < 0)
        fatal_error("kuKernelAllocMemBlock(data @0x%08X) = 0x%08X", (unsigned)opt.field_C, (unsigned)data_blk);
    void *data_ptr = NULL;
    sceKernelGetMemBlockBase(data_blk, &data_ptr);
    if ((uintptr_t)text_ptr != MACHO_SLIDE + text_vm || (uintptr_t)data_ptr != MACHO_SLIDE + data_vm)
        fatal_error("Segments not at fixed base: text %p data %p", text_ptr, data_ptr);

    // Executable thunk arena
    opt.field_C = MACHO_SLIDE + data_vm + data_size;
    SceUID thunk_blk = kuKernelAllocMemBlock("macho_thunks", SCE_KERNEL_MEMBLOCK_TYPE_USER_RX, THUNK_ARENA_SIZE, &opt);
    if (thunk_blk < 0)
        fatal_error("kuKernelAllocMemBlock(thunks @0x%08X) = 0x%08X", (unsigned)opt.field_C, (unsigned)thunk_blk);
    void *thunk_ptr = NULL;
    sceKernelGetMemBlockBase(thunk_blk, &thunk_ptr);
    thunk_head = (uint32_t *)thunk_ptr;
    thunk_end = thunk_head + (THUNK_ARENA_SIZE / 4);

    // Copy segment contents
    text_buf = malloc(text_size);
    memset(text_buf, 0, text_size);
    memcpy(text_buf, d + seg_text->fileoff, seg_text->filesize);

    memset(data_ptr, 0, data_size);
    memcpy(data_ptr, d + seg_data->fileoff, seg_data->filesize);

    // Initialize special sections
    for (int i = 0; i < nsects_total; i++) {
        section *s = sects[i];
        if (!strcmp(s->sectname, "__mod_init_func")) {
            mod_init_addr = MACHO_SLIDE + s->addr;
            mod_init_count = s->size / 4;
        }
    }

    // Resolve dynamic symbol imports (indirect symbols and pointer stubs)
    sym_cache = calloc(nsyms, sizeof(uintptr_t));
    if (dysym) {
        uint32_t *indirect = (uint32_t *)(d + dysym->indirectsymoff);
        for (int s_idx = 0; s_idx < nsects_total; s_idx++) {
            section *s = sects[s_idx];
            uint32_t sect_type = s->flags & 0xFF; // type lives in the low byte of flags
            if (sect_type == S_NON_LAZY_SYMBOL_POINTERS || sect_type == S_LAZY_SYMBOL_POINTERS) {
                uint32_t nslots = s->size / 4;
                uint32_t *slots = (uint32_t *)(MACHO_SLIDE + s->addr);
                for (uint32_t i = 0; i < nslots; i++) {
                    uint32_t sym_idx = indirect[s->reserved1 + i];
                    // INDIRECT_SYMBOL_LOCAL slots are slid by rebase.bin (tools/macho_prep.py)
                    if (!(sym_idx & (INDIRECT_SYMBOL_LOCAL | INDIRECT_SYMBOL_ABS)))
                        slots[i] = resolve_sym(sym_idx);
                }
            }
        }

        // External relocations (vtables -> __cxa_pure_virtual, ObjC classes, CFString isa...).
        // r_address is relative to the first segment (__PAGEZERO, vmaddr 0); in-place word is the addend.
        uint32_t *rel = (uint32_t *)(d + dysym->extreloff);
        for (uint32_t i = 0; i < dysym->nextrel; i++) {
            uint32_t addr = rel[i * 2], info = rel[i * 2 + 1];
            if ((info >> 24) != 0x0C) // r_extern=1, r_length=2 (32-bit), r_pcrel=0, type GENERIC_RELOC_VANILLA
                fatal_error("Unsupported external relocation info 0x%08X at 0x%08X", (unsigned)info, (unsigned)addr);
            *guest_word(addr) += resolve_sym(info & 0xFFFFFF);
        }
        l_info("Imports bound: %u external relocations, %d unimplemented, thunks %u/%u",
               (unsigned)dysym->nextrel, unimpl_count, (unsigned)(THUNK_ARENA_SIZE / 4 - (thunk_end - thunk_head)) / 4,
               (unsigned)(THUNK_ARENA_SIZE / 16));
    }

    // Apply offline rebase relocations
    if (rebase_path)
        apply_rebase(rebase_path);

    // Copy final __TEXT to executable memory block
    kuKernelCpuUnrestrictedMemcpy((void *)(MACHO_SLIDE + text_vm), text_buf, text_size);
    kuKernelFlushCaches((void *)(MACHO_SLIDE + text_vm), text_size);
    free(text_buf);
    text_buf = NULL;
    free(sym_cache);
    sym_cache = NULL;

    l_info("Mach-O loaded successfully.");
    return 0;
}

void macho_run_inits(void) {
    if (!mod_init_addr || !mod_init_count)
        return;
    l_info("Executing %u global constructors (__mod_init_func)...", (unsigned)mod_init_count);
    uint32_t *funcs = (uint32_t *)mod_init_addr;
    for (uint32_t i = 0; i < mod_init_count; i++) {
        if (funcs[i]) {
            l_debug("init %u/%u -> 0x%08X", (unsigned)i + 1, (unsigned)mod_init_count, (unsigned)(funcs[i] - MACHO_SLIDE));
            call_guest((void *)funcs[i], 0, 0, 0, 0); // already slid by rebase.bin
        }
    }
    l_info("global constructors: %u done", (unsigned)mod_init_count);
}
